const P = 122990000;          // monto total prestado
const r = 0.0137;             // tasa mensual
const N = 84;                 // plazo total en meses
const FECHA_PRIMERA = "2026-07-30";

const items = $input.all().map(i => i.json);

const pagos = items.map(it => ({
  id: it.id || "",
  cuota: it.name || it.property_cuota || "",
  numero: it.property_n ?? null,
  fecha: it.property_fecha?.start || it.property_fecha || null,
  monto: it.property_monto_pagado ?? 0,
  capital: it.property_capital ?? null,
  interes: it.property_interés ?? it.property_interes ?? null,
  saldo: it.property_saldo_pendiente ?? null,
  tipo: it.property_tipo_de_pago ?? "",
  notas: it.property_notas ?? ""
}));

const cuotasMensuales = pagos.filter(p => p.tipo === "Cuota mensual");
const cuotasPagadas = cuotasMensuales.length;
const capitalTotalPagado = pagos.reduce((a, p) => a + (p.capital || 0), 0);
const interesTotalPagado = pagos.reduce((a, p) => a + (p.interes || 0), 0);
const ultimo = pagos[pagos.length - 1] || null;
const saldoActual = ultimo ? (ultimo.saldo ?? null) : P;

// cuota fija teórica (sistema francés), sin seguros ni gastos
const cuotaIdeal = P * r / (1 - Math.pow(1 + r, -N));

// simula el crédito "de libro" mes a mes para comparar
let saldoIdeal = P, interesIdealAcumulado = 0, interesIdealTotal = 0, saldoTemp = P;
for (let m = 1; m <= N; m++) {
  const interesMes = saldoTemp * r;
  const capitalMes = cuotaIdeal - interesMes;
  saldoTemp -= capitalMes;
  interesIdealTotal += interesMes;
  if (m <= cuotasPagadas) {
    interesIdealAcumulado += interesMes;
    saldoIdeal = saldoTemp;
  }
}

const fin = new Date(FECHA_PRIMERA + "T00:00:00");
fin.setMonth(fin.getMonth() + (N - 1));

return [{
  json: {
    credito: { montoInicial: P, tasaMensual: r, plazoMeses: N, fechaPrimeraCuota: FECHA_PRIMERA, fechaFinEstimada: fin.toISOString().slice(0,10) },
    resumen: {
      cuotasPagadas, plazoMeses: N,
      saldoActual,
      capitalTotalPagado, interesTotalPagado,
      cuotaTeoricaSinSeguros: Math.round(cuotaIdeal),
      saldoIdealAEstaAltura: Math.round(saldoIdeal),
      interesIdealAEstaAltura: Math.round(interesIdealAcumulado),
      diferenciaSaldo: Math.round(saldoIdeal - (saldoActual ?? saldoIdeal)),
      diferenciaInteres: Math.round(interesIdealAcumulado - interesTotalPagado),
      interesTotalProyectadoDelCredito: Math.round(interesIdealTotal)
    },
    pagos,
    // cuotas que registró Armoni solo con el pago PSE (capital e interés calculados): falta confirmarlas con el extracto
    porVerificar: pagos.filter(p => /registrada (sola|desde)/i.test(p.notas || "") && !/verificada/i.test(p.notas || "")).map(p => ({ numero: p.numero, fecha: p.fecha, monto: p.monto }))
  }
}];

// Prepara la pregunta para la IA: la fecha de hoy (para que sepa qué mes corre), las cuotas reales de «Pago del Carro»
// (con cuáles calculó Armoni solo y falta confirmar) y la foto que mandó la familia convertida en imagen para la IA.
const b = $('Webhook1').first().json.body || {};
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const ahora = new Date(Date.now() - 5 * 3600 * 1000);   // hora de Colombia
const hoy = ahora.toISOString().slice(0, 10);
const mesEnCurso = MESES[ahora.getUTCMonth()] + ' de ' + ahora.getUTCFullYear();
const num = v => (typeof v === 'number' ? v : (Number(v) || 0));
const pagos = $input.all().map(i => i.json).filter(x => x && x.id).map(x => ({
  n: num(x.property_n), fecha: (x.property_fecha && x.property_fecha.start) || x.property_fecha || '',
  monto: num(x.property_monto_pagado), capital: num(x.property_capital), interes: num(x.property_interés ?? x.property_interes),
  gastos: num(x.property_gastos_y_seguros), saldo: num(x.property_saldo_pendiente), tipo: x.property_tipo_de_pago || '', notas: x.property_notas || ''
})).filter(p => p.n > 0).sort((a, c) => a.n - c.n);
const porConfirmar = pagos.filter(p => /registrada (sola|desde)/i.test(p.notas) && !/verificada/i.test(p.notas));
const fmt = n => '$' + Math.round(n).toLocaleString('es-CO').replace(/,/g, '.');
const lineas = pagos.map(p => 'Cuota ' + p.n + ' · ' + p.fecha + ' · pagado ' + fmt(p.monto) + ' · capital ' + fmt(p.capital) + ' · interés ' + fmt(p.interes) +
  ' · gastos y seguros ' + fmt(p.gastos) + ' · saldo ' + fmt(p.saldo) + ' · ' + p.tipo + (porConfirmar.includes(p) ? ' · (CALCULADA POR ARMONI con el pago PSE: falta confirmar con el extracto)' : ''));
// proyección exacta con la tasa y la cuota REALES (las cuentas de amortización no se le dejan a la IA: se equivoca)
let proy = '';
// tasa y cuota: de la última CUOTA MENSUAL (un abono extra no sirve); el saldo, del último registro (cuota o abono)
const cms = pagos.filter(p => /cuota/i.test(p.tipo));
const ucm = cms[cms.length - 1], antCm = ucm ? pagos.filter(p => p.n < ucm.n).pop() : null;
const ult = pagos[pagos.length - 1], ant = antCm;
if (ult && ucm && antCm && ult.saldo > 0 && antCm.saldo > 0) {
  const r = ucm.interes / antCm.saldo, C = ucm.capital + ucm.interes;
  const M = n => '$' + (n / 1e6).toFixed(1).replace('.', ',') + ' millones';
  let s = ult.saldo, filas = [], fact = [], k = 0;
  const marcas = [1, 2, 3, 6, 9, 12, 18, 24, 36, 48, 60];
  while (s > 0 && k < 120) { s = s * (1 + r) - C; k++; if (marcas.includes(k)) filas.push(k + ' cuotas más → saldo ' + M(Math.max(0, s)) + ' (capital abonado ' + M(ult.saldo - Math.max(0, s)) + ')'); }
  const faltan = k;
  marcas.filter(n => n <= 36).forEach(n => fact.push('n=' + n + ': ' + Math.pow(1 + r, n).toFixed(4)));
  proy = '[PROYECCIÓN EXACTA (úsala SIEMPRE; nunca hagas tú la amortización ni restes cuotas completas como capital: la mayor parte de cada cuota es interés)\n' +
    'Tasa real ' + (r * 100).toFixed(3).replace('.', ',') + '% mensual · cuota sin seguros ' + fmt(C) + ' · saldo hoy ' + fmt(ult.saldo) + ' · con cuotas normales faltan ' + faltan + ' cuotas.\n' +
    'Saldo si solo pagan la cuota normal:\n' + filas.join('\n') + '\n' +
    'ABONOS EXTRA A CAPITAL (reduciendo plazo): un abono A hecho hoy baja el saldo dentro de n meses en A × (1+r)^n. Para llegar a un saldo objetivo T dentro de n meses: A = (saldo a n meses − T) ÷ (1+r)^n. Factores (1+r)^n: ' + fact.join(' · ') + '.\n' +
    'Si el abono se reparte en varios meses, cada abono vale un poco menos (menos meses ahorrando interés): da el valor de hacerlo hoy y aclara que si lo reparten sube un poco. Muestra la cuenta en una línea.]\n';
}
const m = typeof b.imagen === 'string' && b.imagen.match(/^data:(image\/[a-z+]+);base64,(.+)$/);
const cab = '[HOY: ' + hoy + ' · mes en curso: ' + mesEnCurso + ']\n' +
  '[CUOTAS EN «PAGO DEL CARRO» (datos reales de Notion):\n' + (lineas.join('\n') || '(ninguna)') + ']\n' +
  (porConfirmar.length ? '[POR CONFIRMAR: ' + porConfirmar.map(p => 'Cuota ' + p.n + ' (' + p.fecha + ')').join(', ') + ' — los valores de capital, interés, seguros y saldo los calculó Armoni; el banco puede tener cifras un poco distintas]\n' : '') +
  proy + (m ? '[LA FAMILIA ADJUNTÓ UNA IMAGEN: está en este mensaje, léela con cuidado]\n' : '') + '\n';
const out = { json: { chatInput: cab + String(b.chatInput || ''), sessionId: String(b.sessionId || 'credito'), conImagen: !!m } };
if (m) out.binary = { data: { data: m[2], mimeType: m[1], fileName: 'extracto.' + m[1].split('/')[1].replace('+xml', '') } };
return [out];

// Lee la respuesta de la IA. Si la familia ya confirmó unos valores, la IA agrega al final un bloque
// <<ACCION {...}>> con lo que hay que guardar en «Pago del Carro». Aquí se valida, se completa lo que falte
// y se decide si se corrige una cuota que ya existe o se crea una nueva. El bloque nunca se le muestra a la familia.
const txt = String($input.first().json.output || '');
const mm = txt.match(/<<\s*ACCION\s*(\{[\s\S]*?\})\s*>>/i);
const texto = txt.replace(/<<\s*ACCION[\s\S]*?>>/ig, '').replace(/\n{3,}/g, '\n\n').trim();
let a = null;
try { a = mm ? JSON.parse(mm[1]) : null; } catch (e) { a = null; }
const num = v => { const n = typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^\d.,-]/g, '').replace(/\./g, '').replace(',', '.')); return Number.isFinite(n) ? n : NaN; };
const r2 = n => Math.round(n * 100) / 100;
const pagos = $('Pagos (chat)').all().map(i => i.json).filter(x => x && x.id).map(x => ({
  id: x.id, n: Number(x.property_n) || 0, fecha: (x.property_fecha && x.property_fecha.start) || x.property_fecha || '',
  saldo: Number(x.property_saldo_pendiente) || 0, notas: x.property_notas || '', tipo: x.property_tipo_de_pago || ''
})).filter(p => p.n > 0).sort((p, q) => p.n - q.n);
const sinAccion = (motivo) => [{ json: { texto, hacer: '', motivo: motivo || '' } }];
if (!a || !['corregir', 'registrar'].includes(a.tipo)) return sinAccion();

const fecha = /^\d{4}-\d{2}-\d{2}$/.test(String(a.fecha || '')) ? a.fecha : '';
const monto = num(a.monto), interes = num(a.interes), gastos = Number.isFinite(num(a.gastos)) ? num(a.gastos) : 0;
if (!(monto > 0) || !(interes >= 0) || !fecha) return sinAccion('faltan datos');
const clase = ['Cuota mensual', 'Abono → reducir plazo', 'Abono → reducir cuota'].includes(a.clase) ? a.clase : 'Cuota mensual';
// el capital es lo que queda del pago después de interés y seguros (si la IA trajo otro número y no cuadra, manda la cuenta)
let capital = num(a.capital);
if (!(capital >= 0) || Math.abs(capital + interes + gastos - monto) > Math.max(2000, monto * 0.01)) capital = r2(monto - interes - gastos);
// ¿qué cuota es? la que dice la IA, o la del mismo mes; si es una cuota mensual de un mes que ya está, se corrige en vez de duplicarla
let fila = a.tipo === 'corregir' ? pagos.find(p => p.n === Number(a.n)) : null;
if (!fila && clase === 'Cuota mensual') fila = pagos.find(p => p.fecha.slice(0, 7) === fecha.slice(0, 7) && p.tipo === 'Cuota mensual');
const n = fila ? fila.n : ((pagos.length ? pagos[pagos.length - 1].n : 0) + 1);
const antes = pagos.filter(p => p.n < n).pop();
let saldo = num(a.saldo);
if (!(saldo > 0) && antes) saldo = r2(antes.saldo - capital);
if (!(saldo > 0)) return sinAccion('falta el saldo');
const nota = 'Verificada con el extracto · ' + new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10) + (fila && /CUS\s*\d+/.test(fila.notas) ? ' · ' + fila.notas.match(/PSE · CUS\s*\d+/)?.[0] : '');
return [{ json: { texto, hacer: fila ? 'corregir' : 'registrar', id: fila ? fila.id : '', n, titulo: clase === 'Cuota mensual' ? 'Cuota ' + n : 'Abono ' + n,
  fecha, monto: r2(monto), capital: r2(capital), interes: r2(interes), gastos: r2(gastos), saldo: r2(saldo), clase, notas: nota } }];

// Lo que ve la familia: la respuesta de la IA y, si se guardó algo en «Pago del Carro», la confirmación.
const a = $('Leer acción').first().json;
let texto = a.texto || 'Listo.';
let guardado = false;
if (a.hacer) {
  const nodo = a.hacer === 'corregir' ? 'Corregir cuota' : 'Registrar pago';
  let r = null; try { r = $(nodo).first().json; } catch (e) { r = null; }
  const fmt = n => '$' + Math.round(n).toLocaleString('es-CO').replace(/,/g, '.');
  if (r && r.id && !r.error) {
    guardado = true;
    texto += '\n\n✅ ' + (a.hacer === 'corregir' ? 'Corregí la ' : 'Registré la ') + a.titulo + ' en Pago del Carro: capital ' + fmt(a.capital) + ', interés ' + fmt(a.interes) + ', seguros ' + fmt(a.gastos) + ', saldo ' + fmt(a.saldo) + '.';
  } else texto += '\n\n⚠️ No pude guardarlo en Notion. Revisa la conexión de Notion en el flujo «IA Credito Carro».';
}
return [{ json: { output: texto, guardado } }];
